        TEST_ASSERT_EQUAL(true, set_dma_configure_polling(&ch_sel, DMA_WIDTH_WORD, DMA_BSIZE_16, DMA_WIDTH_WORD, DMA_BSIZE_16, false, DMA_CACHE_SYNC_AUTO));

        //DMA configure 1: src/dst addr WORD aligned
