        ch_sel = ch;
        TEST_ASSERT_EQUAL(true, set_dma_configure(&ch_sel, DMA_WIDTH_WORD, DMA_BSIZE_16, DMA_WIDTH_BYTE, DMA_BSIZE_64, false, DMA_CACHE_SYNC_AUTO));

        // DMA configure 8: src BYTE aligned, burst_size = 64
        ch_sel = ch;
        TEST_ASSERT_EQUAL(true, set_dma_configure(&ch_sel, DMA_WIDTH_BYTE, DMA_BSIZE_64, DMA_WIDTH_WORD, DMA_BSIZE_16, false, DMA_CACHE_SYNC_AUTO));

        // DMA configure 9: src/dst addr decrease
        ch_sel = ch;
        TEST_ASSERT_EQUAL(true, set_dma_configure(&ch_sel, DMA_WIDTH_WORD, DMA_BSIZE_16, DMA_WIDTH_WORD, DMA_BSIZE_16, true, DMA_CACHE_SYNC_AUTO));

        // DMA configure 10: burst size 1
        ch_sel = ch;
        TEST_ASSERT_EQUAL(true, set_dma_configure(&ch_sel, DMA_WIDTH_WORD, DMA_BSIZE_1, DMA_WIDTH_WORD, DMA_BSIZE_16, false, DMA_CACHE_SYNC_AUTO));
        
        // // DMA configure 11: burst size 4
        ch_sel = ch;
        TEST_ASSERT_EQUAL(true, set_dma_configure(&ch_sel, DMA_WIDTH_WORD, DMA_BSIZE_4, DMA_WIDTH_WORD, DMA_BSIZE_16, false, DMA_CACHE_SYNC_AUTO));

        // DMA configure 12: burst size 8
        ch_sel = ch;
        TEST_ASSERT_EQUAL(true, set_dma_configure(&ch_sel, DMA_WIDTH_WORD, DMA_BSIZE_8, DMA_WIDTH_WORD, DMA_BSIZE_16, false, DMA_CACHE_SYNC_AUTO));

        // DMA configure 13: burst size 32
        ch_sel = ch;
        TEST_ASSERT_EQUAL(true, set_dma_configure(&ch_sel, DMA_WIDTH_WORD, DMA_BSIZE_32, DMA_WIDTH_WORD, DMA_BSIZE_16, false, DMA_CACHE_SYNC_AUTO));

        // DMA configure 14: burst size 64
        ch_sel = ch;
        TEST_ASSERT_EQUAL(true, set_dma_configure(&ch_sel, DMA_WIDTH_WORD, DMA_BSIZE_64, DMA_WIDTH_WORD, DMA_BSIZE_16, false, DMA_CACHE_SYNC_AUTO));
        
        // // DMA configure 15: burst size 128
        ch_sel = ch;
        TEST_ASSERT_EQUAL(true, set_dma_configure(&ch_sel, DMA_WIDTH_WORD, DMA_BSIZE_128, DMA_WIDTH_WORD, DMA_BSIZE_16, false, DMA_CACHE_SYNC_AUTO));

        // DMA configure 16: burst size 256
        ch_sel = ch;
        TEST_ASSERT_EQUAL(true, set_dma_configure(&ch_sel, DMA_WIDTH_WORD, DMA_BSIZE_256, DMA_WIDTH_WORD, DMA_BSIZE_16, false, DMA_CACHE_SYNC_AUTO));

        // DMA configure 17: burst size 32 (dst)
        ch_sel = ch;
        TEST_ASSERT_EQUAL(true, set_dma_configure(&ch_sel, DMA_WIDTH_WORD, DMA_BSIZE_16, DMA_WIDTH_WORD, DMA_BSIZE_32, false, DMA_CACHE_SYNC_AUTO));

