void test_dma_suspend_resume(void)
{
    uint8_t ch, ch_sel;

    for (ch = 0; ch < DMA_NUMBER_OF_CHANNELS; ch++)  // DMA_NUMBER_OF_CHANNELS
    {
        // DMA configure 21: initially SUSP only
        ch_sel = ch;
        TEST_ASSERT_EQUAL(true, set_dma_configure_suspen(&ch_sel, DMA_CACHE_SYNC_AUTO, true));

        // // DMA configure 22: SUSP + Enable
        ch_sel = ch;
        TEST_ASSERT_EQUAL(true, set_dma_configure_suspen(&ch_sel, DMA_CACHE_SYNC_AUTO, false));

        // DMA configure 23: Disable channel only
        ch_sel = ch;
        TEST_ASSERT_EQUAL(true, set_dma_configure_dis(&ch_sel, DMA_CACHE_SYNC_AUTO, true));

        // DMA configure 24: Start Xfer, and then SUSP only
        ch_sel = ch;
        TEST_ASSERT_EQUAL(true, set_dma_configure_suspresm(&ch_sel, DMA_CACHE_SYNC_AUTO, true));

        // DMA configure 25: Start Xfer, and then SUSP & Resume
        ch_sel = ch;
        TEST_ASSERT_EQUAL(true, set_dma_configure_suspresm(&ch_sel, DMA_CACHE_SYNC_AUTO, false));
    }
}

